ROOT=Path(__file__).resolve().parents[1];bank=json.loads((ROOT/'public/data/questions-ocr.json').read_text());by={q['id']:q for q in bank}
def S(w,n,text=None,options=None):
 q=by[f'week{w}-q{n}']
 if text is not None:q['questionText']=text
 if options is not None:
  opts=options.split('||') if isinstance(options,str) else options
  old=q['options'];q['options']=[dict(old[i],text=t) if i<len(old) else {'id':chr(65+i),'text':t,'restored':True} for i,t in enumerate(opts)]
for q in bank:
 q['officialCorrectAnswers']=q['correctAnswers'];q['answerOrigin']='PDF accepted-answer label'
 q['transcriptionStatus']='visually-reviewed'
 for item in [q]+q['options']:
  key='questionText' if 'questionText' in item else 'text'
  t=item[key].replace('at-\ntributed','attributed').replace('direc-\ntion','direction')
  for a,b in [('muiti','multi'),('finear','linear'),('Faise','False'),('leaming','learning'),('Leaming','Learning'),('Cario','Carlo'),('Carto','Carlo'),('sampIe','sample'),('sampie','sample'),('sampie','sample'),('quarantee','guarantee'),('refiect','reflect'),('GP!','GPI'),('GP1','GPI'),('siowly','slowly'),('trajectory Jength','trajectory length'),('cali-graph','call-graph'),('grid-wortd','grid-world'),('retumed','returned'),('neéd','need'),('not s correct','not a correct')]:t=t.replace(a,b)
  item[key]=t
 # Restore conventional two-choice spelling from visually checked source.
 if q['type']=='true-false':
  for o in q['options']:o['text']='True' if o['id']==('A' if q['id']!='week7-q5' else 'B') else 'False'
